node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get Emma's orders
const orders = db.prepare(\"SELECT * FROM orders WHERE user_id = 'cust_001'\").all();
console.log('Orders:', JSON.stringify(orders, null, 2));

// Get order items
for (const o of orders) {
  const items = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all(o.order_id);
  console.log('Items for order ' + o.order_id + ':', JSON.stringify(items, null, 2));
}

// Get order payments
for (const o of orders) {
  const payments = db.prepare('SELECT * FROM order_payments WHERE order_id = ?').all(o.order_id);
  console.log('Payments for order ' + o.order_id + ':', JSON.stringify(payments, null, 2));
}

// Get order fulfillments
for (const o of orders) {
  const fulfillments = db.prepare('SELECT * FROM order_fulfillments WHERE order_id = ?').all(o.order_id);
  console.log('Fulfillments for order ' + o.order_id + ':', JSON.stringify(fulfillments, null, 2));
}

// Check rt_payment_methods for Emma
const pms = db.prepare(\"SELECT * FROM rt_payment_methods WHERE user_id = 'cust_001'\").all();
if (pms.length) console.log('RT Payment Methods:', JSON.stringify(pms, null, 2));

// Check warranties
const warranties = db.prepare(\"SELECT * FROM warranties WHERE user_id = 'cust_001'\").all();
if (warranties.length) console.log('Warranties:', JSON.stringify(warranties, null, 2));
"

