node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check all tables for any loyalty-related config
const allTables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all().map(t => t.name);
for (const t of allTables) {
  const rows = db.prepare('SELECT * FROM ' + t + ' LIMIT 1').all();
  const cols = Object.keys(rows[0] || {});
  const loyaltyCols = cols.filter(c => c.toLowerCase().includes('loyalty') || c.toLowerCase().includes('redeem') || c.toLowerCase().includes('point'));
  if (loyaltyCols.length) {
    console.log(t + ' has loyalty columns:', loyaltyCols);
  }
}
"

