const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Step 1: Update CI-0006 quantity from 3 to 2
db.prepare(\"UPDATE cart_items SET quantity = 2 WHERE cart_item_id = 'CI-0006' AND cart_id = 'CART-user_58b0a2d6'\").run();
console.log('✅ Updated CI-0006 quantity to 2');

// Step 2: Remove CI-0005 from cart_items
db.prepare(\"DELETE FROM cart_items WHERE cart_item_id = 'CI-0005' AND cart_id = 'CART-user_58b0a2d6'\").run();
console.log('✅ Removed CI-0005');

// Step 3: Recalculate cart totals
// CI-0006: 2 × \$89 = \$178
// CI-0007: 2 × \$72 = \$144
// New subtotal = \$322
const newSubtotal = (2 * 89) + (2 * 72);  // 178 + 144 = 322
const shippingCost = 0; // was free standard shipping
const newTotal = newSubtotal + shippingCost;

const newItemIds = JSON.stringify(['CI-0006', 'CI-0007']);

db.prepare(\"UPDATE carts SET subtotal = ?, total = ?, item_ids_json = ? WHERE cart_id = 'CART-user_58b0a2d6'\")
  .run(newSubtotal, newTotal, newItemIds);
console.log('✅ Updated cart totals');

// Verify final state
const cart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_58b0a2d6'\").get();
console.log('\nUpdated Cart:', JSON.stringify(cart, null, 2));

const items = db.prepare(\"SELECT * FROM cart_items WHERE cart_id = 'CART-user_58b0a2d6'\").all();
console.log('\nRemaining Items:', JSON.stringify(items, null, 2));
"
